#include "gridengine/editor.hpp"
#include "gridengine/engine.hpp"
#include "gridengine/project.hpp"
#include "gridengine/scene.hpp"
#include "gridengine/tilemap.hpp"
#include <algorithm>
#include <cassert>
#include <cmath>
#include <filesystem>
#include <fstream>
#include <limits>
namespace { bool close(double a,double b){return std::abs(a-b)<1e-8;} }
int main(){
 gridengine::Engine engine; assert(!engine.initialized()); assert(engine.initialize()); assert(engine.initialized()); engine.shutdown(); assert(!engine.initialized());
 gridengine::Engine invalid({"",60}); assert(!invalid.initialize());
 const auto root=std::filesystem::temp_directory_path()/"gridengine_v04_smoke"; std::error_code ec; std::filesystem::remove_all(root,ec);
 const auto created=gridengine::create_project(root,"Smoke Test"); assert(created); assert(std::filesystem::exists(root/"scenes")); assert(std::filesystem::exists(root/"assets")); assert(gridengine::open_project(created.project.file)); assert(!gridengine::create_project(root,"Bad/Name"));
 gridengine::Scene scene; const auto parent=scene.create_entity("Parent"),child=scene.create_entity("Child"); scene.find(parent)->transform.position={10,20}; scene.find(parent)->transform.rotation=90; scene.find(parent)->transform.scale={2,3}; scene.find(child)->transform.position={4,2}; const auto before=scene.world_transform(child); assert(scene.set_parent(child,parent)); const auto after=scene.world_transform(child); assert(close(before.position.x,after.position.x)&&close(before.position.y,after.position.y)); assert(close(before.rotation,after.rotation)); assert(!scene.set_parent(parent,child)); assert(scene.rename_entity(child,"Renamed")); scene.find(child)->sprite=gridengine::Sprite2D{"texture with spaces.png",false,0x123456ff}; scene.find(child)->camera=gridengine::Camera2D{false,2.5};
 const auto clone=scene.duplicate_entity(child); assert(clone); assert(scene.find(*clone)->sprite&&scene.find(*clone)->sprite->texture=="texture with spaces.png"); assert(scene.find(*clone)->camera&&!scene.find(*clone)->camera->enabled); const auto nested=scene.create_entity("Nested",child); assert(nested); const auto subtree=scene.duplicate_entity(child); assert(subtree&&scene.find(*subtree)->children.size()==1);
 scene.find(child)->motion=gridengine::Motion2D{{2,-1},90}; const auto wb=scene.world_transform(child); assert(scene.update(.5)); const auto wa=scene.world_transform(child); assert(close(wa.position.x,wb.position.x+1)); assert(close(wa.position.y,wb.position.y-.5)); assert(close(wa.rotation,wb.rotation+45)); const auto safe=scene.world_transform(child); assert(!scene.update(-1)); assert(close(scene.world_transform(child).position.x,safe.position.x));
 gridengine::Scene atomic_scene; const auto moving=atomic_scene.create_entity("Moving"); const auto zero_parent=atomic_scene.create_entity("Zero Parent"); const auto blocked=atomic_scene.create_entity("Blocked",zero_parent); atomic_scene.find(moving)->motion=gridengine::Motion2D{{10,0},0}; atomic_scene.find(zero_parent)->transform.scale={0,1}; atomic_scene.find(blocked)->motion=gridengine::Motion2D{{1,0},0}; assert(!atomic_scene.update(1)); assert(close(atomic_scene.find(moving)->transform.position.x,0));
 const auto other=scene.create_entity("Overlap"); scene.find(other)->transform.position=scene.world_transform(child).position; scene.find(child)->collider=gridengine::Collider2D{{2,2},true}; scene.find(other)->collider=gridengine::Collider2D{{1,1},true}; auto pairs=scene.collisions(); const auto child_other=std::pair{std::min(child,other),std::max(child,other)}; assert(std::binary_search(pairs.begin(),pairs.end(),child_other)); assert(std::is_sorted(pairs.begin(),pairs.end())); assert(std::adjacent_find(pairs.begin(),pairs.end())==pairs.end()); scene.find(other)->transform.position.x+=100; assert(scene.collisions().empty()); scene.find(other)->transform.position.x-=100; scene.find(child)->collider->half_extents.x=-2; assert(scene.collisions().empty()); scene.find(child)->collider->half_extents.x=2; scene.find(other)->collider->enabled=false; assert(scene.collisions().empty()); scene.find(other)->collider->enabled=true;
 const auto sf=root/"scenes"/"test.scene"; assert(scene.save(sf)); const auto loaded=gridengine::Scene::load(sf); assert(loaded&&loaded->entities().size()==scene.entities().size()); assert(loaded->find(child)->collider&&loaded->find(child)->collider->enabled); assert(close(loaded->find(child)->collider->half_extents.x,2)); const auto old=root/"scenes"/"old.scene"; {std::ofstream out(old);out<<"GridScene 1\nE 1 0 \"Old\" 0 0 0 1 1 0 0\n";} assert(gridengine::Scene::load(old)); const auto malformed=root/"scenes"/"bad.scene"; {std::ofstream out(malformed);out<<"GridScene 3\nE 1 0 \"Missing transform fields\"\n";} assert(!gridengine::Scene::load(malformed));
 gridengine::TileMap2D map(3,2,16,24); assert(map.width()==3&&map.height()==2&&map.tile_count()==0); assert(map.set_cell(2,1,{42,0xabcdef12})); assert(!map.set_cell(3,0,{1})); assert(map.cell(2,1)->tile_id==42&&map.cell(2,1)->tint==0xabcdef12); assert(close(map.cell_center(2,1).x,40)&&close(map.cell_center(2,1).y,36)); const auto pos=map.cell_at({39.9,35.9}); assert(pos&&pos->first==2&&pos->second==1); assert(!map.cell_at({48,0})); assert(map.tile_count()==1); assert(map.clear_cell(2,1)&&map.tile_count()==0); gridengine::TileMap2D oversized(1000001,2); assert(oversized.empty());
 // Finite tile dimensions whose multiplied map extent overflows must be rejected.
 const double huge=std::numeric_limits<double>::max(); gridengine::TileMap2D overflow_map(2,1,huge,1); assert(overflow_map.empty());
 assert(map.set_cell(1,1,{7,0x11223344})); const auto tf=root/"scenes"/"test.tiles"; assert(map.save(tf)); const auto reloaded=gridengine::TileMap2D::load(tf); assert(reloaded&&reloaded->width()==3&&reloaded->cell(1,1)->tile_id==7&&reloaded->cell(1,1)->tint==0x11223344); const auto badtiles=root/"scenes"/"bad.tiles"; {std::ofstream out(badtiles);out<<"GridTileMap2D 1\n3 2 16 24\n1 2\n";} assert(!gridengine::TileMap2D::load(badtiles)); const auto huge_tiles=root/"scenes"/"huge.tiles"; {std::ofstream out(huge_tiles);out<<"GridTileMap2D 1\n2 1 "<<std::numeric_limits<double>::max()<<" 1\n0 4294967295\n0 4294967295\n";} assert(!gridengine::TileMap2D::load(huge_tiles));
 assert(scene.remove_entity(parent)); assert(scene.find(child)==nullptr); assert(!scene.remove_entity(parent));
 gridengine::Editor editor; const auto eroot=editor.create_entity("Root"); const auto echild=editor.scene().create_entity("Child",eroot); assert(editor.select(eroot)); assert(!editor.select(999999)); auto tree=editor.hierarchy(); assert(tree.size()==2&&tree[0].depth==0&&tree[1].id==echild&&tree[1].depth==1); assert(editor.select(echild)); assert(editor.rename_selected("Renamed Child")); assert(editor.set_transform({{5,7},25,{2,3}})); assert(!editor.set_transform({{NAN,0},0,{1,1}})); assert(editor.set_sprite(gridengine::Sprite2D{"sprite.png",false,0x112233ff})); assert(editor.set_camera(gridengine::Camera2D{true,1.5})); const auto eclone=editor.duplicate_selected(); assert(eclone&&editor.selection()==eclone); assert(editor.scene().find(*eclone)->sprite->texture=="sprite.png"); assert(editor.reparent_selected(eroot)); const auto ef=root/"scenes"/"editor.scene"; assert(editor.save_scene(ef)); gridengine::Editor reopened; assert(reopened.load_scene(ef)); assert(!reopened.selection()); const auto loaded_tree=reopened.hierarchy(); assert(loaded_tree.size()==3&&loaded_tree[0].id==eroot&&loaded_tree[0].depth==0&&loaded_tree[1].depth==1&&loaded_tree[2].depth==1); assert(reopened.select(eroot)); assert(reopened.remove_selected()); assert(!reopened.selection());
 std::filesystem::remove_all(root,ec);
}
